export const BESTIARY_CATEGORIES = [...new Set(BESTIARY.map(t => t.category))];
export function bestiaryById(id: string) { return BESTIARY.find(t => t.id === id); }

/** Leitura dos ataques das tabelas do PDF para uso nos dados de combate.
 *  A ficha continua 100% editável: a lista é reextraída do texto atualizado.
 */
export type BestiaryAttack = { name: string; attribute: number; hit: string; damage: string; critical: string };
const cleanDice = (line: string) => {
  const source = line.replace(/^(?:Dano|Crítico):\s*/i, '').split(/\s+\(média/i)[0]?.trim() ?? '';
  const valid = source.match(/^(\d+d(?:4|6|8|10|12|20)(?:\s*\+\s*(?:\d+d(?:4|6|8|10|12|20)|\d+))*)/i);
  return valid?.[1] ?? '';
};
export function readBestiaryAttacks(text: string): BestiaryAttack[] {
  const lines = text.split(/\r?\n/).map(x => x.trim()).filter(Boolean);
  const result: BestiaryAttack[] = [];
  for (let i = 0; i < lines.length; i++) {
    const hit = lines[i]?.match(/1d20\s*\+\s*1d(4|6|8|10|12)\b/i);
    if (!hit) continue;
    const die = Number(hit[1]);
    let name = lines[i - 1] || 'Ataque';
    // Títulos de ataques podem vir quebrados em duas linhas no PDF (ex.: 'Rapieira (1 por' / 'rodada)').
    if (/^rodada\)|^ataques?\s+por\s+rodada/i.test(name) && i > 1) name = `${lines[i - 2]} ${name}`;
    const next = lines[i + 1] ?? '';
    const damage = cleanDice(next);
    const critical = cleanDice(lines[i + 2] ?? '');
    result.push({ name: name.startsWith('Ataque:') ? 'Ataque principal' : name, attribute: ({4:1,6:2,8:3,10:4,12:5} as Record<number, number>)[die] ?? 1,
      hit: hit[0], damage, critical });
  }
  return result;
}

/** Rola uma expressão de dados do livro (ex. 1d12 + 1d10 + 4) sem alterar os limites de nomenclatura. */
export function rollBestiaryDice(expression: string) {
  const cleaned = expression.replace(/\s+/g, '');
  if (!/^(?:\d+d(?:4|6|8|10|12|20)|\d+)(?:\+(?:\d+d(?:4|6|8|10|12|20)|\d+))*$/i.test(cleaned)) return null;
  const dice: number[] = [];
  let modifier = 0;
  for (const part of cleaned.split('+')) {
    const die = part.match(/^(\d+)d(4|6|8|10|12|20)$/i);
    if (!die) { modifier += Number(part); continue; }
    const count = Number(die[1]); const faces = Number(die[2]);
    if (count > 30 || dice.length + count > 30) return null;
    for (let i = 0; i < count; i++) dice.push(Math.floor(Math.random() * faces) + 1);
  }
  return { expression, dice, modifier, total: dice.reduce((a,b)=>a+b, modifier) };
}
